),
revenda as (select '7afe4da5-e846-4b02-947f-96843a2791fe'::uuid as id)
insert into public.pa_wqi_baixas (
  revenda_id, data_ocorrido, turno, produto_id, produto_codigo, produto_descricao,
  quantidade, unidade, unidades_equivalentes, hl_calculado, motivo, local,
  responsavel_nome, colaborador_nome, origem, origem_ref, criado_em
)
select
  r.id,
  (d.criado_em::timestamptz at time zone 'America/Sao_Paulo')::date,
  d.turno,
  p.id,
  d.codigo,
  coalesce(p.descricao, d.descricao, 'Produto ' || d.codigo),
  d.quantidade,
  d.unidade,
  case
    when d.unidade = 'unidade' then d.quantidade
    when p.unidades_por_caixa > 0 then d.quantidade * p.unidades_por_caixa
  end,
  case
    when p.fator_hecto is null then null
    when d.unidade = 'caixa' then round(d.quantidade * p.fator_hecto, 3)
    when p.unidades_por_caixa > 0 then round(d.quantidade::numeric / p.unidades_por_caixa * p.fator_hecto, 3)
  end,
  d.motivo,
  d.local,
  d.responsavel,
  coalesce(d.email, 'Planilha WQI'),
  'planilha',
  d.idwqi,
  d.criado_em::timestamptz
from dados d
cross join revenda r
left join public.pa_produtos p on p.revenda_id = r.id and p.codigo = d.codigo
on conflict (revenda_id, origem_ref) where origem_ref is not null do nothing;

-- Confira: 2215 baixas importadas; quantas acharam o produto e o HL.
select
  count(*) as baixas_da_planilha,
  count(produto_id) as com_produto_no_cadastro,
  count(hl_calculado) as com_hl
from public.pa_wqi_baixas
where origem = 'planilha';